    @Test
    public void testCollatedIteratorWithMultipleSortedIterators() {
        Comparator<Integer> comparator = Integer::compare;

        List<Integer> list1 = Arrays.asList(1, 5, 10);
        List<Integer> list2 = Arrays.asList(2, 3, 12);
        List<Integer> list3 = Arrays.asList(0, 6, 7);

        Collection<Iterator<? extends Integer>> iterators = new ArrayList<>();
        iterators.add(list1.iterator());
        iterators.add(list2.iterator());
        iterators.add(list3.iterator());

        Iterator<Integer> result = IteratorUtils.collatedIterator(comparator, iterators);

        List<Integer> expected = Arrays.asList(0, 1, 2, 3, 5, 6, 7, 10, 12);
        List<Integer> actual = new ArrayList<>();
        while (result.hasNext()) {
            actual.add(result.next());
        }

        assertEquals("The collated iterator should return elements in sorted order across all iterators", expected, actual);
    }

    @Test
    public void testCollatedIteratorWithEmptyIterators() {
        Comparator<Integer> comparator = Integer::compare;

        Collection<Iterator<? extends Integer>> iterators = new ArrayList<>();
        iterators.add(Collections.emptyIterator());
        iterators.add(Arrays.asList(1, 2).iterator());
        iterators.add(Collections.emptyIterator());

        Iterator<Integer> result = IteratorUtils.collatedIterator(comparator, iterators);

        List<Integer> actual = IteratorUtils.toList(result);
        assertEquals(Arrays.asList(1, 2), actual);
    }

    @Test
    public void testCollatedIteratorWithEmptyCollection() {
        Comparator<Integer> comparator = Integer::compare;
        Collection<Iterator<? extends Integer>> iterators = Collections.emptyList();

        Iterator<Integer> result = IteratorUtils.collatedIterator(comparator, iterators);

        assertFalse("Iterator should be empty when collection of iterators is empty", result.hasNext());
    }

    @Test
    public void testCollatedIteratorWithStrings() {
        Comparator<String> comparator = String::compareTo;

        Collection<Iterator<? extends String>> iterators = new ArrayList<>();
        iterators.add(Arrays.asList("apple", "cherry").iterator());
        iterators.add(Arrays.asList("banana", "date").iterator());

        Iterator<String> result = IteratorUtils.collatedIterator(comparator, iterators);

        List<String> expected = Arrays.asList("apple", "banana", "cherry", "date");
        List<String> actual = new ArrayList<>();
        while (result.hasNext()) {
            actual.add(result.next());
        }

        assertEquals(expected, actual);
    }

    @Test
    public void testCollatedIteratorWithSingleIterator() {
        Comparator<Integer> comparator = Integer::compare;
        List<Integer> list = Arrays.asList(3, 1, 2);
        // Note: The input iterators themselves don't have to be sorted, 
        // but the collated iterator treats them as streams to be merged via comparator.
        // However, typical usage assumes the individual iterators are already sorted.
        // If they aren't, the behavior depends on the implementation (usually a priority queue merge).

        Collection<Iterator<? extends Integer>> iterators = Collections.singletonList(Arrays.asList(1, 3, 5).iterator());

        Iterator<Integer> result = IteratorUtils.collatedIterator(comparator, iterators);

        List<Integer> actual = IteratorUtils.toList(result);
        assertEquals(Arrays.asList(1, 3, 5), actual);
    }

    @Test
    public void testCollatedIteratorWithDuplicateElements() {
        Comparator<Integer> comparator = Integer::compare;

        Collection<Iterator<? extends Integer>> iterators = new ArrayList<>();
        iterators.add(Arrays.asList(1, 2, 2).iterator());
        iterators.add(Arrays.asList(2, 3).iterator());

        Iterator<Integer> result = IteratorUtils.collatedIterator(comparator, iterators);

        List<Integer> expected = Arrays.asList(1, 2, 2, 2, 3);
        List<Integer> actual = IteratorUtils.toList(result);

        assertEquals(expected, actual);
    }
